thread_local! {
    pub(in crate::execution::runtime_core) static LAST_ASSIGN_ERROR: std::cell::RefCell<Option<String>> = std::cell::RefCell::new(None);
}

pub(in crate::execution::runtime_core) fn get_assign_error(
    name: &str,
    default_to_const: bool,
) -> String {
    LAST_ASSIGN_ERROR
        .with(|cell| cell.borrow_mut().take())
        .unwrap_or_else(|| {
            if default_to_const {
                format!("Cannot assign to const '{}'", name)
            } else {
                format!("Undefined '{}'", name)
            }
        })
}

/// Helper to pop next mock input value from global playback queue
pub fn get_playback_input() -> Option<String> {
    INPUT_PLAYBACK
        .get_or_init(|| Mutex::new(VecDeque::new()))
        .lock()
        .ok()
        .and_then(|mut q| q.pop_front())
}

pub struct Interpreter {
    #[allow(private_interfaces)]
    pub(crate) envs: Vec<Env>,
    free_envs: Vec<usize>, // Free list for scope recycling (memory safety)
    global: usize,
    current_module: Option<String>,
    /// If a runtime `throw` occurs during evaluation, the interpreter stores
    /// the structured LangError here so surrounding exec layers (try/catch)
    /// can inspect and bind it as a `Value::Error`.
    pending_throw: Option<LangError>,
    // microtask queue (promises, timers)
    microtasks: VecDeque<Box<dyn FnOnce(&mut dyn InterpreterEnv) + 'static>>,
    microtasks_running: bool,
    // timer/event channel: other threads send timer events (timer id) to main interpreter
    timer_rx: Option<mpsc::Receiver<u64>>,
    timer_manager: Option<Arc<TimerManager>>,
    // timers registry: id -> TimerEntry
    timer_entries: HashMap<u64, TimerEntry>,
    next_timer_id: u64,
    // promises table
    promises: HashMap<u64, PromiseEntry>,
    // next_promise_id removed in favor of global PROMISE_COUNTER
    // native-side effects queue used by native closures to request interpreter-side actions
    native_side_effects: Arc<Mutex<Vec<NativeEffect>>>,
    method_cache: HashMap<(Arc<str>, Arc<str>), UserFn>,
    // Memoization cache for pure recursive numeric function evaluations.
    recursion_memo: HashMap<(String, i64), Value>,
    // Purity status cache for user functions.
    pure_fn_cache: HashMap<String, bool>,
    pub method_cache_hits: usize,
    pub method_cache_lookups: usize,
    // Adaptive memory config for dynamic recursion limits
    #[allow(dead_code)]
    adaptive_memory: crate::memory::adaptive::AdaptiveMemoryConfig,
    #[cfg(debug_assertions)]
    exec_depth: usize,
    #[cfg(debug_assertions)]
    call_stack: Vec<String>,
    // Track if were in pre-registration phase (to skip decorator application)
    in_pre_registration: bool,
    // Track current class context for visibility checking
    current_class_context: Option<String>,
    // Skip main() execution when loading modules (used in test mode)
    skip_main_on_module_load: bool,
    /// Current function name for tail-call optimization (TCO).
    /// When a `return f(args)` is detected where `f` matches this name,
    /// the interpreter emits `Flow::TailCall` instead of recursing.
    tco_current_fn: Option<String>,
}

#[derive(Clone)]
struct TimerEntry {
    callback: Value,
    cancel_flag: Arc<AtomicBool>,
    is_interval: bool,
}

// Trait used to allow native builtin closures to accept either the main
// Interpreter or an Exec instance running a user function. This keeps the
// native function ABI consistent while avoiding duplicating builtin logic.
use crate::parsing::ast::BuiltinEnv;
use chrono::{Datelike, Timelike};
use std::io::Read;

impl BuiltinEnv for Interpreter {
    fn as_any_mut(&mut self) -> &mut dyn Any {
        self
    }
    fn native_side_effects(&self) -> Option<Arc<Mutex<Vec<NativeEffect>>>> {
        Some(self.native_side_effects.clone())
    }
    fn create_promise_executor(&mut self, executor: Value) -> Result<Value, String> {
        let id = PROMISE_COUNTER.fetch_add(1, Ordering::SeqCst);
        // Register promise entry
        self.promises.insert(
            id,
            PromiseEntry {
                state: PromiseState::Pending,
                handlers: Vec::new(),
            },
        );

        // Build native resolve/reject functions
        let resolve_fn = Value::Function(NativeFn(std::sync::Arc::new(
            move |env: &mut dyn BuiltinEnv, args: Vec<Value>| {
                if args.len() < 1 {
                    return Err(err("resolve expects 1 arg"));
                }
                env.schedule_resolve(id, args[0].clone());
                Ok(Value::Null)
            },
        )));
        let reject_fn = Value::Function(NativeFn(std::sync::Arc::new(
            move |env: &mut dyn BuiltinEnv, args: Vec<Value>| {
                if args.len() < 1 {
                    return Err(err("reject expects 1 arg"));
                }
                env.schedule_reject(id, args[0].clone());
                Ok(Value::Null)
            },
        )));

        // If executor is a native function, call directly; if user function, call in interpreter context
        match executor {
            Value::Null => {}
            Value::Function(NativeFn(f)) => {
                let _ = (f)(self, vec![resolve_fn, reject_fn]);
            }
            Value::UserFunction(u) => {
                // Execute user-defined executor within interpreter with proper closure
                let fn_env = self.acquire_scope(Some(u.closure));
                if u.params.len() >= 1 {
                    self.envs[fn_env]
                        .values
                        .insert(u.params[0].0.clone(), resolve_fn.clone());
                }
                if u.params.len() >= 2 {
                    self.envs[fn_env]
                        .values
                        .insert(u.params[1].0.clone(), reject_fn.clone());
                }
                let mut executor_error: Option<String> = None;
                for s in u.body.iter() {
                    match self.exec_stmt(
                        s,
                        fn_env,
                        &mut ModuleLoader::new(std::path::Path::new(".")),
                        "<promise_executor>".into(),
                    ) {
                        Ok(Flow::Next) | Ok(Flow::Return(_)) | Ok(Flow::TailCall(_, _)) => {}
                        Ok(Flow::Break) | Ok(Flow::Continue) | Ok(Flow::Jump(_)) => {}
                        Err(e) => {
                            executor_error = Some(e.to_string());
                            break;
                        }
                    }
                }
                // Release the scope for recycling (memory safety)
                self.release_scope(fn_env);
                if let Some(e) = executor_error {
                    self.settle_promise_reject(id, Value::Str(e));
                }
            }
            _ => return Err(err("Promise executor must be a function")),
        }

        // Return promise id value
        Ok(Value::Promise(id))
    }
    fn schedule_resolve(&mut self, id: u64, v: Value) {
        // directly settle
        self.settle_promise_fulfill(id, v);
        // immediately drain any native side effects produced
        self.drain_native_side_effects();
        self.run_microtasks();
    }
    fn schedule_reject(&mut self, id: u64, v: Value) {
        self.settle_promise_reject(id, v);
        self.drain_native_side_effects();
        self.run_microtasks();
    }
    // timers
    fn alloc_timer_id(&mut self) -> Result<u64, String> {
        let id = self.next_timer_id;
        self.next_timer_id += 1;
        Ok(id)
    }
    fn get_timer_sender(&self) -> Option<mpsc::Sender<u64>> {
        self.timer_manager.as_ref().map(|m| m.sender())
    }
    fn register_timer(
        &mut self,
        id: u64,
        callback: Value,
        cancel_flag: Arc<AtomicBool>,
        is_interval: bool,
        ms: u64,
    ) -> Result<(), String> {
        self.timer_entries.insert(
            id,
            TimerEntry {
                callback,
                cancel_flag: cancel_flag.clone(),
                is_interval,
            },
        );
        if let Some(mgr) = &self.timer_manager {
            mgr.spawn_timer(id, cancel_flag.clone(), is_interval, ms);
        }
        Ok(())
    }
    fn cancel_timer(&mut self, id: u64) -> Result<(), String> {
        if let Some(entry) = self.timer_entries.remove(&id) {
            entry.cancel_flag.store(false, Ordering::SeqCst);
        }
        if let Some(mgr) = &self.timer_manager {
            mgr.cancel_timer(id);
        }
        Ok(())
    }
    // (drive_event_loop implemented as an inherent method on Interpreter)
}

