        self.define_builtin("makeChannel", |_ctx, _args| {
            let (tx, rx) = mpsc::channel::<Value>();
            let tx_arc = std::sync::Arc::new(std::sync::Mutex::new(tx));
            let rx_arc = std::sync::Arc::new(std::sync::Mutex::new(rx));
            let mut obj = HashMap::default();
            let tx_clone = tx_arc.clone();
            obj.insert("send".into(), Value::Function(NativeFn(std::sync::Arc::new(move |_env: &mut dyn BuiltinEnv, args: Vec<Value>| {
                if args.len() != 1 { return Err(err("send(value)")); }
                let _ = tx_clone.lock().unwrap().send(args[0].clone());
                Ok(Value::Null)
            }))));
            let rc_arc = rx_arc.clone();
            obj.insert("recv".into(), Value::Function(NativeFn(std::sync::Arc::new(move |env: &mut dyn BuiltinEnv, _args: Vec<Value>| {
                let rc_local = rc_arc.clone();
                let _ = env.create_promise_executor(Value::Function(NativeFn(std::sync::Arc::new(move |benv: &mut dyn BuiltinEnv, a: Vec<Value>| {
                    let resolve = a.get(0).cloned().unwrap_or(Value::Null);
                    let value = rc_local.clone();
                    let id = benv.alloc_timer_id()?;
                    let cb = Value::Function(NativeFn(std::sync::Arc::new(move |env2: &mut dyn BuiltinEnv, _ax: Vec<Value>| {
                        if let Ok(v) = value.lock().unwrap().try_recv() {
                            if let Value::Function(NativeFn(f)) = resolve.clone() { let _ = (f)(env2, vec![v]); }
                            let _ = env2.cancel_timer(id);
                        }
                        Ok(Value::Null)
                    })));
                        let flag = Arc::new(AtomicBool::new(true));
                        benv.register_timer(id, cb, flag.clone(), true, 1)?;
                        if let Some(tx) = benv.get_timer_sender() {
                            eprintln!("[debug] spawning makeChannel recv timer id={} interval=1ms", id);
                            std::thread::spawn(move || {
                                while flag.load(Ordering::SeqCst) {
                                    std::thread::sleep(std::time::Duration::from_millis(1));
                                    eprintln!("[debug] makeChannel timer sending id={}", id);
                                    let _ = tx.send(id);
                                }
                            });
                        }
                    Ok(Value::Null)
                }))));
                Ok(Value::Null)
            }))));
            Ok(Value::Object(obj.into()))
        });

