                    if let Some(v) = loader.cache.get(&full) {
                        self.define_at(env, alias.clone(), v.clone(), None);
                        return Ok(Flow::Next);
                    }
                    let mut lex = Lexer::new(process_src);
                    let toks = lex.tokenize().map_err(|e| RunErr::Msg(err(e)))?;
                    let mut p = Parser::new(toks, Some(full.clone()));
                    let prog = p.parse_program().map_err(|e| err(e))?;
